import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {spawnSync} from 'node:child_process';
import {createHash} from 'node:crypto';
const root='output/recon-retained-source-recovery-20261005';
const sha=x=>createHash('sha256').update(x).digest('hex');
function section(patch,file){let active=false;const out=[];for(const line of patch.replace(/\r\n/g,'\n').split('\n')){if(line.startsWith('*** Update File: ')){active=line.replace(/\\/g,'/').endsWith('/'+file);continue;}if(line.startsWith('*** ')){active=false;continue;}if(active)out.push(line);}return out;}
function apply(source,lines){const chunks=[];let chunk=[];for(const line of lines){if(line.startsWith('@@')){if(chunk.length)chunks.push(chunk);chunk=[];}else if(/^[ +\-]/.test(line))chunk.push(line);}if(chunk.length)chunks.push(chunk);let text=source.replace(/\r\n/g,'\n');for(const c of chunks){const before=c.filter(x=>x[0]!=='+').map(x=>x.slice(1)).join('\n'),after=c.filter(x=>x[0]!=='-').map(x=>x.slice(1)).join('\n');if(!before)throw new Error('Unanchored context');const i=text.indexOf(before);if(i<0)throw new Error('Missing captured context: '+before.split('\n')[0].slice(0,90));if(text.indexOf(before,i+1)>=0)throw new Error('Ambiguous context');text=text.slice(0,i)+after+text.slice(i+before.length);}return text;}
const plans=[{name:'engine',file:'src/lib/recon-engine.ts',parent:[1],child:[1,2,3],pre:'4e677bab86dc28c71d322d947b3abe1f42c0865ef618a5b3834c959b54eb4c02',post:'523644c6137e5beb91a0ae0eebc616d58b7201f822b3f41eca07ad82f7742647'},{name:'recons',file:'src/components/recons-tab.tsx',parent:[2,3],child:[6,7,8],pre:'5169d6a0831fc72eab964cb1570baecfee0d4750111ceb93bee58c3606faa501',post:'5768b300a8f4a508935204b25a969448bc9863df45f3a1b0b8807f20e1db5842'}];
await mkdir(root+'/parent-combined',{recursive:true});const results=[];
for(const p of plans){let stage='parent';try{const g=spawnSync('git',['show','989fda7:'+p.file],{maxBuffer:2000000});if(g.status!==0)throw new Error('Approved Git image unavailable');let text=g.stdout.toString();for(const n of p.parent)text=apply(text,section(await readFile(root+'/parent-source-literals/patch-'+String(n).padStart(3,'0')+'.txt','utf8'),p.file));const preVariants=[text,text.replace(/\r?\n/g,'\r\n')],exactPre=preVariants.find(x=>sha(x)===p.pre);const preHashes=preVariants.map(sha);stage='child';for(const n of p.child)text=apply(text,section(await readFile(root+'/patches/patch-'+String(n).padStart(3,'0')+'.txt','utf8'),p.file));const variants=[text,text.replace(/\r?\n/g,'\r\n')],exact=variants.find(x=>sha(x)===p.post);if(exact)await writeFile(root+'/parent-combined/'+p.name+'-EXACT.txt',exact,{flag:'wx'});results.push({name:p.name,exactPre:!!exactPre,preHashes,exactPost:!!exact,postHashes:variants.map(sha)});}catch(e){results.push({name:p.name,stage,exactPost:false,reason:e.message});}}
await writeFile(root+'/parent-combined/RECEIPT-'+Date.now()+'.json',JSON.stringify({at:new Date().toISOString(),results,workingRuntimeChanged:false,oldCommandsReplayed:false},null,2),{flag:'wx'});console.log(JSON.stringify(results));
